package it.cavallium.rockserver.distributed.ratis;

import it.cavallium.rockserver.core.common.*;
import it.cavallium.rockserver.core.common.distributed.*;
import it.cavallium.rockserver.core.impl.RWScheduler;
import it.cavallium.rockserver.core.impl.rocksdb.*;
import java.io.IOException;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.LongSupplier;
import static it.cavallium.rockserver.distributed.ratis.RatisSnapshotCohortRpc.*;

/** One process/pool owner. Exact started requests never enter a replacement capture factory. */
public final class RatisSnapshotCohortService implements AutoCloseable {
    public record Limits(int cohorts,long metadataBytes,int actions){public Limits{if(cohorts<1 || cohorts>4 || metadataBytes<MAX_REQUEST_BYTES || metadataBytes>128L*1024*1024 || actions<1 || actions>2)throw new IllegalArgumentException("Invalid cohort service limits");}public static Limits defaults(){return new Limits(4,128L*1024*1024,2);}}
    public record Member(ReplicatedRangeStore store,RatisSnapshotPins registry,RatisSnapshotOwner owner,ReplicaDescriptor replica,long admissionGeneration,long currentTerm,byte[] configurationDigest,ApplyPosition completedCut){public Member{Objects.requireNonNull(store);Objects.requireNonNull(registry);Objects.requireNonNull(owner);Objects.requireNonNull(replica);Objects.requireNonNull(completedCut);if(admissionGeneration<0 || currentTerm<=0 || configurationDigest.length!=32 || completedCut.term()!=currentTerm)throw new IllegalArgumentException("Invalid actual cohort qualification");configurationDigest=configurationDigest.clone();}@Override public byte[] configurationDigest(){return configurationDigest.clone();}}
    /** Actor supplies actual division/current-native-cut qualification outside its monitors, never caller-selected paths. */
    public interface Host {
        UUID nodeId();UUID nodeIncarnation();UUID processIncarnation();UUID poolId();DistributedStoragePool pool();PoolSnapshotAdmission.Limits poolLimits();
        Member member(UUID group,SnapshotFence fence,boolean ready)throws Exception;
    }
    private static final class Owned {final Member member;final RatisSnapshotPins.ExternalReservation reservation;Owned(Member member,RatisSnapshotPins.ExternalReservation reservation){this.member=member;this.reservation=reservation;}}
    private static final class Entry {final Request request;final Reference reference;final long bytes,opened;final List<Owned> owned=new ArrayList<>();Map<UUID,RatisSnapshotCaptureRequest.Result> results=Map.of();DistributedStoragePool.SnapshotCohort cohort;int readers;boolean busy=true,started,cancelled,lost,released,cleaning;Entry(Request request,long bytes,long opened){this.request=request;reference=reference(request);this.bytes=bytes;this.opened=opened;}}
    private final Host host;private final RWScheduler scheduler;private final Limits limits;private final LongSupplier nanos;private final Map<UUID,Entry> entries=new LinkedHashMap<>();private final Map<UUID,Reference> released=new LinkedHashMap<>();private long metadataBytes,actionBytes;private int actions,controls;private boolean stopping;
    public RatisSnapshotCohortService(Host host,RWScheduler scheduler,Limits limits,LongSupplier nanos){this.host=Objects.requireNonNull(host);this.scheduler=Objects.requireNonNull(scheduler);this.limits=Objects.requireNonNull(limits);this.nanos=Objects.requireNonNull(nanos);Objects.requireNonNull(host.pool());Objects.requireNonNull(host.poolLimits());}
    public Capabilities capabilities(UUID group)throws Exception {var member=host.member(group,null,false);var registry=member.registry.limits();var used=member.registry.stats();var pool=host.poolLimits();var retained=host.pool().snapshotAdmissionStats();var pressure=host.pool().currentSnapshotPressure();int current;long bytes;synchronized(this){if(stopping)throw new IOException("Cohort service stopping");current=entries.size();bytes=metadataBytes;}return new Capabilities(host.nodeId(),host.nodeIncarnation(),host.processIncarnation(),host.poolId(),limits.cohorts,current,limits.metadataBytes,bytes,registry.captures(),used.entries(),registry.bytes(),used.bytes(),registry.maximumTtl().toMillis(),pool.maximumPins(),pressure.pinReservations(),pool.maximumEstimatedBytes(),retained.estimatedBytes(),pool.maximumAge().toMillis(),pressure.estimatedBytes(),pressure.freeBytes(),pool.minimumFreeBytes());}
    public RatisSnapshotOwner owner(UUID group,SnapshotFence fence)throws Exception {var member=host.member(group,fence,true);var actual=member.owner;return new RatisSnapshotOwner(actual.groupId(),actual.rangeEpoch(),actual.schemaDigest(),actual.incarnation(),actual.peerId(),capabilities(group));}
    /** Copies/decodes only after bounded action admission. CAPTURE is dispatched as shared BATCH work. */
    public CompletableFuture<byte[]> query(UUID anchor,int kind,byte[] body)throws IOException {
        Objects.requireNonNull(body);if(kind==STATE || kind==CANCEL){if(body.length!=96)throw new IOException("Invalid cohort control reference");synchronized(this){if(controls>=16)throw new IOException("Cohort control admission exhausted");controls++;}try{return CompletableFuture.completedFuture(reply(kind==STATE?state(reference(body)):cancel(reference(body))));}catch(Throwable failure){return CompletableFuture.failedFuture(failure);}finally{synchronized(this){controls--;}}}if(body.length>MAX_REQUEST_BYTES-ScopedTransactionRpc.HEADER_BYTES)throw new IOException("Cohort frame exceeds bound");long charge=4L*body.length+2L*MAX_REPLY_BYTES; synchronized(this){if(stopping || actions>=limits.actions || charge>limits.metadataBytes-metadataBytes-actionBytes)throw new IOException("Cohort action admission exhausted");actions++;actionBytes+=charge;}var copy=body.clone();var result=new CompletableFuture<byte[]>();
        final class Work implements Runnable,RWScheduler.RejectionAwareTask {boolean claimed;private synchronized boolean claim(){if(claimed)return false;claimed=true;return true;}public void reject(RuntimeException failure){if(claim())finish(null,failure);}public void run(){if(!claim())return;try{byte[] reply=switch(kind){case OWNER->owner(anchor,RatisSnapshotCaptureRequest.decode(copy).fence()).encode();case CAPTURE->{var request=request(copy);if(!request.cohort().members().getFirst().groupId().equals(anchor))throw new IOException("Cohort anchor changed");yield reply(capture(request));}case STATE->reply(state(reference(copy)));case CANCEL->reply(cancel(reference(copy)));default->throw new IOException("Unsupported cohort operation");};finish(reply,null);}catch(Throwable failure){finish(null,failure);}}private void finish(byte[] value,Throwable failure){synchronized(RatisSnapshotCohortService.this){actions--;actionBytes-=charge;}if(failure==null)result.complete(value);else result.completeExceptionally(failure);}}
        var work=new Work();try{scheduler.executor(WorkloadProfile.BATCH,OperationFamily.METADATA,Long.MAX_VALUE).execute(work,Math.min(charge,WorkloadCost.MAX_ESTIMATED_BYTES));}catch(RuntimeException rejected){work.reject(rejected);}return result;
    }
    private void process(Reference reference)throws IOException {if(!reference.nodeIncarnation().equals(host.nodeIncarnation()) || !reference.processIncarnation().equals(host.processIncarnation()) || !reference.poolId().equals(host.poolId()))throw new RatisSnapshotLostException("Original cohort process/pool no longer exists");}
    private Entry existing(Reference reference)throws IOException {process(reference);var entry=entries.get(reference.cohortId());if(entry==null)throw new RatisSnapshotLostException("Original cohort is not retained");if(!Arrays.equals(reference(reference),reference(entry.reference)))throw new IOException("Cohort identity changed original request");return entry;}
    public Reply capture(Request request)throws Exception {
        byte[] encoded=request(request);var reference=reference(request);process(reference);final Entry entry;
        synchronized(this){var old=released.get(reference.cohortId());if(old!=null){if(!Arrays.equals(reference(old),reference(reference)))throw new IOException("Released cohort request changed");return new Reply(reference,Phase.RELEASED,Map.of());}var previous=entries.get(reference.cohortId());if(previous!=null){entry=existing(reference);if(entry.busy)return new Reply(reference,Phase.PENDING,Map.of());}else{if(stopping)throw new IOException("Cohort service stopping");long bytes=4L*encoded.length+256L*request.cohort().members().size();if(entries.size()>=limits.cohorts || entries.size()+released.size()>=1024 || bytes>limits.metadataBytes-metadataBytes-actionBytes)throw new IOException("Cohort metadata admission exhausted");entry=new Entry(request,bytes,nanos.getAsLong());entries.put(reference.cohortId(),entry);metadataBytes+=bytes;}}
        if(!entry.owned.isEmpty() || entry.started || entry.lost || entry.cancelled || entry.released)return live(entry);
        Throwable failure=null;try {
            for(var expected:request.cohort().members()){synchronized(this){if(entry.cancelled || stopping)throw new IOException("Cohort cancelled before physical capture");}var capture=request.captures().get(expected.groupId());var member=host.member(expected.groupId(),capture.fence(),true);if(!member.owner.peerId().equals(member.replica.peerId()) || member.owner.rangeEpoch()!=capture.fence().participant(expected.groupId()).rangeEpoch() || !Arrays.equals(member.owner.schemaDigest(),capture.fence().participant(expected.groupId()).schemaDigest()) || !member.owner.incarnation().equals(expected.owner()) || !member.owner.groupId().equals(expected.groupId()) || !member.replica.replicaId().equals(expected.replica()) || !member.replica.nodeId().equals(host.nodeId()) || !member.replica.nodeIncarnation().equals(host.nodeIncarnation()) || member.replica.role()!=ReplicaDescriptor.Role.VOTER)throw new IOException("Cohort actual member/owner changed");var reservation=member.registry.reserveExternal(capture,()->{try{return member.store.snapshotRetentionFloor();}catch(Exception unavailable){throw new IllegalStateException(unavailable);}});entry.owned.add(new Owned(member,reservation));}
            var pressure=host.pool().currentSnapshotPressure();var poolLimits=host.poolLimits();var retained=host.pool().snapshotAdmissionStats();if(pressure.pinReservations()>=poolLimits.maximumPins() || pressure.estimatedBytes()>poolLimits.maximumEstimatedBytes()-retained.estimatedBytes() || pressure.freeBytes()<poolLimits.minimumFreeBytes())throw new IOException("Fresh pool pressure exceeds cohort admission");synchronized(this){entry.started=true;}for(var owned:entry.owned)owned.member.registry.markPhysicalStarted(owned.reservation);synchronized(this){if(entry.cancelled || stopping)throw new IOException("Cohort cancelled before native capture");}
            entry.cohort=host.pool().captureGateCohort(entry.owned.stream().map(o->new DistributedStoragePool.GateCaptureRequest(o.member.store,request.captures().get(o.member.owner.groupId()).fence())).toList());var captures=new HashMap<UUID,RatisSnapshotCaptureRequest.Result>();for(var owned:entry.owned){var group=owned.member.owner.groupId();requireUnchanged(owned.member,host.member(group,request.captures().get(group).fence(),true),entry.cohort.pins().get(group).position());var pin=owned.member.store.scopeCohortPin(entry.cohort.pins().get(group),request.captures().get(group).fence());var adopted=owned.member.registry.publishExternal(owned.reservation,pin);captures.put(group,new RatisSnapshotCaptureRequest.Result(adopted.token(),null));}for(var owned:entry.owned){var group=owned.member.owner.groupId();requireUnchanged(owned.member,host.member(group,request.captures().get(group).fence(),true),entry.cohort.pins().get(group).position());}entry.results=Map.copyOf(captures);
        }catch(Throwable problem){failure=problem;synchronized(this){entry.lost=true;entry.cancelled=true;}}
        finally{synchronized(this){entry.busy=false;}if(failure!=null)try{cleanup(entry);}catch(Throwable cleanup){failure.addSuppressed(cleanup);}}
        if(failure instanceof Exception exception)throw exception;if(failure instanceof Error error)throw error;return live(entry);
    }
    private static void requireUnchanged(Member before,Member after,ApplyPosition captured)throws IOException {
        var a=before.owner;var b=after.owner;if(before.store!=after.store || before.registry!=after.registry || before.admissionGeneration!=after.admissionGeneration || before.currentTerm!=after.currentTerm || !Arrays.equals(before.configurationDigest,after.configurationDigest) || !before.replica.equals(after.replica) || !a.groupId().equals(b.groupId()) || a.rangeEpoch()!=b.rangeEpoch() || !Arrays.equals(a.schemaDigest(),b.schemaDigest()) || !a.incarnation().equals(b.incarnation()) || !a.peerId().equals(b.peerId()) || after.completedCut.index()<captured.index() || after.completedCut.term()<captured.term() || after.completedCut.index()==captured.index() && after.completedCut.term()!=captured.term())throw new IOException("Actual cohort qualification changed during physical capture");
    }
    private Reply live(Entry entry)throws Exception {
        boolean check;synchronized(this){if(entry.busy)return new Reply(entry.reference,Phase.PENDING,Map.of());if(entry.cancelled || entry.lost || expired(entry))entry.cancelled=true;check=!entry.cancelled;if(check)entry.readers++;}
        if(!check){cleanup(entry);return new Reply(entry.reference,entry.released?Phase.RELEASED:Phase.DRAINING,Map.of());}
        try {for(var owned:entry.owned){var current=owned.member.registry.externalLive(owned.reservation);if(!Objects.equals(entry.results.get(owned.member.owner.groupId()).token(),current.token()))throw new RatisSnapshotLostException("Original cohort pin changed");}
            synchronized(this){return new Reply(entry.reference,entry.cancelled?Phase.DRAINING:Phase.CAPTURED,entry.cancelled?Map.of():entry.results);}
        }catch(Exception failure){synchronized(this){entry.cancelled=true;entry.lost=true;}throw failure;}
        finally{boolean cleanup;synchronized(this){entry.readers--;cleanup=entry.cancelled;}if(cleanup)cleanup(entry);}
    }
    private boolean expired(Entry entry){long duration=entry.request.cohort().members().stream().mapToLong(RatisDatabaseBackupJournal.Member::ttlMillis).min().orElseThrow()*1_000_000L;return nanos.getAsLong()-entry.opened>=duration;}
    public Reply state(Reference reference)throws Exception {final Entry entry;synchronized(this){if(released.containsKey(reference.cohortId()))return released(reference);entry=existing(reference);}return live(entry);}
    public Reply cancel(Reference reference)throws Exception {final Entry entry;synchronized(this){if(released.containsKey(reference.cohortId()))return released(reference);entry=existing(reference);entry.cancelled=true;if(entry.busy)return new Reply(reference,Phase.DRAINING,Map.of());}cleanup(entry);return new Reply(reference,entry.released?Phase.RELEASED:Phase.DRAINING,Map.of());}
    private Reply released(Reference reference)throws IOException {process(reference);if(!Arrays.equals(reference(reference),reference(released.get(reference.cohortId()))))throw new IOException("Released cohort identity changed");return new Reply(reference,Phase.RELEASED,Map.of());}
    private void cleanup(Entry entry)throws Exception {
        synchronized(this){if(entry.busy || entry.readers!=0 || entry.cleaning)return;entry.cleaning=true;}try {for(var owned:entry.owned)if(!owned.member.registry.externalSettled(owned.reservation))owned.member.registry.cancelExternal(owned.reservation);
        if(entry.cohort!=null)entry.cohort.close();boolean physicalSettled=entry.cohort==null || entry.cohort.pins().values().stream().allMatch(ReplicatedRangeStore.SnapshotPin::releaseSettled);for(var owned:entry.owned){try{if(physicalSettled && !owned.member.registry.externalSettled(owned.reservation))owned.member.registry.failExternal(owned.reservation);}catch(IOException alreadyTransferred){/* Transferred pins settle through their registry close path. */}owned.member.registry.expire();}
        boolean settled=true;for(var owned:entry.owned)settled&=owned.member.registry.externalSettled(owned.reservation);if(entry.cohort!=null)for(var pin:entry.cohort.pins().values())settled&=pin.releaseSettled();synchronized(this){entry.released=settled;if(settled){if(entry.started){if(released.size()>=1024)throw new IOException("Cohort released identity budget exhausted");released.put(entry.reference.cohortId(),entry.reference);}entries.remove(entry.reference.cohortId());metadataBytes-=entry.bytes;if(entry.started)metadataBytes+=128;}}
        }finally{synchronized(this){entry.cleaning=false;}}
    }
    @Override public void close()throws Exception {final List<Entry> owned;synchronized(this){stopping=true;if(actions!=0 || controls!=0)throw new IOException("Cohort actions remain active");owned=List.copyOf(entries.values());for(var entry:owned)entry.cancelled=true;}for(var entry:owned)cleanup(entry);synchronized(this){if(entries.values().stream().anyMatch(e->!e.released))throw new IOException("Actual cohort native owners remain active");}}
}
